1	/*
2	 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
3	 * AscendC STFT kernel — per-frame windowing + DFT dot product.
4	 * Float32 only.
5	 */
6	#include "kernel_operator.h"
7	class StftKernel {
8	public:
9	    __aicore__ inline void Init(
10	        GM_ADDR frames, GM_ADDR window, GM_ADDR dftReal, GM_ADDR dftImag,
11	        GM_ADDR outReal, GM_ADDR outImag,
12	        int32_t totalFrames, int32_t nFft, int32_t freqBins,
13	        int32_t, int32_t tasksPerCore, int32_t)
14	    {
15	        total_ = totalFrames; nFft_ = nFft; fb_ = freqBins; tpc_ = tasksPerCore;
16	
17	        framesGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(frames),
18	                                   static_cast<uint64_t>(totalFrames) * nFft);
19	        windowGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(window), nFft);
20	        dftRGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(dftReal),
21	                                 static_cast<uint64_t>(freqBins) * nFft);
22	        dftIGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(dftImag),
23	                                 static_cast<uint64_t>(freqBins) * nFft);
24	        outRGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(outReal),
25	                                 static_cast<uint64_t>(totalFrames) * freqBins);
26	        outIGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(outImag),
27	                                 static_cast<uint64_t>(totalFrames) * freqBins);
28	
29	        uint32_t nb = static_cast<uint32_t>(nFft_) * sizeof(float);
30	        uint32_t ob = static_cast<uint32_t>(fb_) * sizeof(float);
31	
32	        // Work buffer size: 2 * CeilPower2(nFft_) * sizeof(float), min 256 bytes
33	        uint32_t ceilP2 = 1;
34	        while (ceilP2 < nb) ceilP2 <<= 1;
35	        uint32_t wbSize = ceilP2 * 2;
36	        if (wbSize < 256) wbSize = 256;
37	
38	        pipe_.InitBuffer(fBuf_, nb);       // frame data (loaded from GM, then holds windowed result)
39	        pipe_.InitBuffer(wBuf_, nb);       // window
40	        pipe_.InitBuffer(dBuf_, nb);       // DFT row
41	        pipe_.InitBuffer(pBuf_, nb);       // intermediate product
42	        pipe_.InitBuffer(rBuf_, wbSize);   // ReduceSum work buffer
43	        pipe_.InitBuffer(aBuf_, static_cast<uint32_t>(sizeof(float)) * 4); // accumulator (4 floats for safety)
44	        pipe_.InitBuffer(oRBuf_, ob);      // output real accumulation
45	        pipe_.InitBuffer(oIBuf_, ob);      // output imag accumulation
46	        pipe_.InitBuffer(outRQ_, 2, ob);   // output real TQue
47	        pipe_.InitBuffer(outIQ_, 2, ob);   // output imag TQue
48	    }
49	
50	    __aicore__ inline void Process() {
51	        using AscendC::DataCopyExtParams;
52	        using AscendC::DataCopyPadExtParams;
53	        const int32_t ci = AscendC::GetBlockIdx();
54	
55	        DataCopyExtParams cp{1, 0, 0, 0, 0};
56	        DataCopyPadExtParams<float> pp(true, 0, 0, 0.0f);
57	        const uint32_t nb = static_cast<uint32_t>(nFft_) * sizeof(float);
58	        const uint32_t ob = static_cast<uint32_t>(fb_) * sizeof(float);
59	
60	        for (int32_t t = 0; t < tpc_; ++t) {
61	            const int32_t fi = ci * tpc_ + t;
62	            if (fi >= total_) continue;
63	
64	            // --- Load frame into TBuf ---
65	            auto frame = fBuf_.Get<float>();
66	            cp.blockLen = nb;
67	            AscendC::DataCopyPad(frame, framesGm_[static_cast<uint64_t>(fi) * nFft_], cp, pp);
68	
69	            // --- Load window into TBuf ---
70	            auto win = wBuf_.Get<float>();
71	            cp.blockLen = nb;
72	            AscendC::DataCopyPad(win, windowGm_, cp, pp);
73	
74	            AscendC::PipeBarrier<PIPE_MTE2>();
75	            AscendC::PipeBarrier<PIPE_ALL>();
76	
77	            // --- Windowing: prod = frame * window ---
78	            auto prod = pBuf_.Get<float>();
79	            AscendC::Mul(prod, frame, win, nFft_);
80	            AscendC::PipeBarrier<PIPE_V>();
81	
82	            // Overwrite frame buffer with windowed result (reuse for DFT loop)
83	            AscendC::DataCopy(frame, prod, nb);
84	            AscendC::PipeBarrier<PIPE_MTE2>();
85	
86	            // --- Output accumulation buffers ---
87	            auto outR = oRBuf_.Get<float>();
88	            auto outI = oIBuf_.Get<float>();
89	            auto dftRow = dBuf_.Get<float>();
90	            auto work = rBuf_.Get<float>();
91	            auto acc = aBuf_.Get<float>();
92	
93	            // --- DFT dot-products per frequency bin ---
94	            for (int32_t k = 0; k < fb_; ++k) {
95	                // Real part: sum(frame[n] * dft_real[k][n])
96	                cp.blockLen = nb;
97	                AscendC::DataCopyPad(dftRow, dftRGm_[static_cast<uint64_t>(k) * nFft_], cp, pp);
98	                AscendC::PipeBarrier<PIPE_MTE2>();
99	                AscendC::PipeBarrier<PIPE_ALL>();
100	                AscendC::Mul(prod, frame, dftRow, nFft_);
101	                AscendC::PipeBarrier<PIPE_V>();
102	                AscendC::ReduceSum<float>(acc, prod, work, nFft_);
103	                AscendC::PipeBarrier<PIPE_V>();
104	                outR.SetValue(k, acc.GetValue(0));
105	
106	                // Imag part: sum(frame[n] * dft_imag[k][n])
107	                cp.blockLen = nb;
108	                AscendC::DataCopyPad(dftRow, dftIGm_[static_cast<uint64_t>(k) * nFft_], cp, pp);
109	                AscendC::PipeBarrier<PIPE_MTE2>();
110	                AscendC::PipeBarrier<PIPE_ALL>();
111	                AscendC::Mul(prod, frame, dftRow, nFft_);
112	                AscendC::PipeBarrier<PIPE_V>();
113	                AscendC::ReduceSum<float>(acc, prod, work, nFft_);
114	                AscendC::PipeBarrier<PIPE_V>();
115	                outI.SetValue(k, acc.GetValue(0));
116	            }
117	
118	            // --- Copy output TBuf → TQue → GM ---
119	            auto oRq = outRQ_.AllocTensor<float>();
120	            auto oIq = outIQ_.AllocTensor<float>();
121	            AscendC::DataCopy(oRq, outR, ob);
122	            AscendC::DataCopy(oIq, outI, ob);
123	            AscendC::PipeBarrier<PIPE_MTE2>();
124	            outRQ_.EnQue(oRq);
125	            outIQ_.EnQue(oIq);
126	
127	            oRq = outRQ_.DeQue<float>();
128	            oIq = outIQ_.DeQue<float>();
129	            cp.blockLen = ob;
130	            AscendC::DataCopyPad(outRGm_[static_cast<uint64_t>(fi) * fb_], oRq, cp);
131	            AscendC::DataCopyPad(outIGm_[static_cast<uint64_t>(fi) * fb_], oIq, cp);
132	            outRQ_.FreeTensor(oRq);
133	            outIQ_.FreeTensor(oIq);
134	        }
135	    }
136	
137	private:
138	    int32_t total_ = 0, nFft_ = 0, fb_ = 0, tpc_ = 0;
139	    AscendC::TPipe pipe_;
140	    AscendC::GlobalTensor<float> framesGm_, windowGm_, dftRGm_, dftIGm_, outRGm_, outIGm_;
141	    AscendC::TBuf<AscendC::TPosition::VECCALC> fBuf_, wBuf_, dBuf_, pBuf_, rBuf_, aBuf_, oRBuf_, oIBuf_;
142	    AscendC::TQue<AscendC::TPosition::VECOUT, 2> outRQ_, outIQ_;
143	};
144	
145	extern "C" __global__ __aicore__ void stft_kernel(
146	    GM_ADDR frames, GM_ADDR window, GM_ADDR dftReal, GM_ADDR dftImag,
147	    GM_ADDR outReal, GM_ADDR outImag,
148	    int32_t totalFrames, int32_t nFft, int32_t freqBins,
149	    int32_t tileFrames, int32_t tasksPerCore, int32_t coreNum)
150	{
151	    StftKernel k;
152	    k.Init(frames, window, dftReal, dftImag, outReal, outImag,
153	           totalFrames, nFft, freqBins, tileFrames, tasksPerCore, coreNum);
154	    k.Process();
155	}
