11	// STFT op_host — tiling calculation + EXEC_KERNEL_CMD launch
12	// The kernel receives pre-extracted frames and pre-computed DFT matrix as input.
13	// Frame extraction and DFT matrix computation are done at the Python level.
14	
15	#include <algorithm>
16	#include <cstdint>
17	#include <vector>
18	
19	#include <torch/extension.h>
20	#include <torch/library.h>
21	
22	#include "torch_kernel_helper.h"
23	#include "tiling/platform/platform_ascendc.h"
24	
25	#include "aclrtlaunch_stft_kernel.h"
26	
27	static inline int32_t CeilDivI32(int32_t a, int32_t b)
28	{
29	    if (b == 0) { return 0; }
30	    return (a + b - 1) / b;
31	}
32	
33	namespace ascend_kernel {
34	
35	std::vector<at::Tensor> stft(
36	    const at::Tensor &frames, const at::Tensor &window,
37	    const at::Tensor &dftReal, const at::Tensor &dftImag,
38	    int64_t nFftVal, int64_t freqBinsVal)
39	{
40	    // Input validation
41	    TORCH_CHECK(frames.dim() == 2, "frames must be [total_frames, n_fft]");
42	    TORCH_CHECK(window.dim() == 1, "window must be [n_fft]");
43	    TORCH_CHECK(dftReal.dim() == 2, "dft_real must be [freq_bins, n_fft]");
44	    TORCH_CHECK(dftImag.dim() == 2, "dft_imag must be [freq_bins, n_fft]");
45	    TORCH_CHECK(frames.scalar_type() == at::kFloat, "only float32 supported");
46	    TORCH_CHECK(frames.is_contiguous(), "frames must be contiguous");
47	    TORCH_CHECK(window.is_contiguous(), "window must be contiguous");
48	    TORCH_CHECK(dftReal.is_contiguous(), "dft_real must be contiguous");
49	    TORCH_CHECK(dftImag.is_contiguous(), "dft_imag must be contiguous");
50	
51	    const int32_t totalFrames = static_cast<int32_t>(frames.sizes()[0]);
52	    const int32_t nFft = static_cast<int32_t>(frames.sizes()[1]);
53	    const int32_t freqBins = static_cast<int32_t>(dftReal.sizes()[0]);
54	
55	    TORCH_CHECK(nFft == static_cast<int32_t>(window.sizes()[0]), "window size mismatch");
56	    TORCH_CHECK(nFft == static_cast<int32_t>(dftReal.sizes()[1]), "dft_real cols mismatch");
57	    TORCH_CHECK(freqBins == static_cast<int32_t>(dftImag.sizes()[0]), "freq_bins mismatch");
58	    TORCH_CHECK(
59	        nFftVal == static_cast<int64_t>(nFft), "n_fft parameter mismatch");
60	    TORCH_CHECK(
61	        freqBinsVal == static_cast<int64_t>(freqBins), "freq_bins parameter mismatch");
62	
63	    // Get platform info
64	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
65	    int32_t usedCoreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
66	
67	    // Per-frame processing: each task = 1 frame
68	    const int32_t cappedCores = std::max<int32_t>(1, std::min<int32_t>(usedCoreNum, totalFrames));
69	    const int32_t tasksPerCore = CeilDivI32(totalFrames, cappedCores);
70	
71	    // Allocate output tensors
72	    at::Tensor outReal = at::empty({totalFrames, freqBins}, frames.options());
73	    at::Tensor outImag = at::empty({totalFrames, freqBins}, frames.options());
74	
75	    // All params as left values (required by EXEC_KERNEL_CMD)
76	    int32_t blockDim = cappedCores;
77	    int32_t tileFrames = 1;
78	
79	    EXEC_KERNEL_CMD(stft_kernel, blockDim,
80	                    frames, window, dftReal, dftImag,
81	                    outReal, outImag,
82	                    totalFrames, nFft, freqBins,
83	                    tileFrames, tasksPerCore, cappedCores);
84	
85	    return {outReal, outImag};
86	}
87	
88	}  // namespace ascend_kernel
